pages.source:
Page(name: "Password reset", route: Route(path: "/reset-password"))

Build(
  Scaffold(
    appBar: BraaiCornerHeader(),
    body: ScrollView(label: "Password reset", child: Column(gap: Space.md, padding: Insets(y: 12), children: [Column(gap: Space.md, padding: Insets(x: 16, y: 8), children: [
    Text(child: "ACCOUNT", size: FontSize.xs, weight: FontWeight.bold, letterSpacing: 2, color: Color.textMuted, fontFamily: "Trebuchet MS"), Text(child: "FORGOTTEN YOUR PASSWORD?", size: FontSize.xxl, weight: FontWeight.bold, letterSpacing: 1, fontFamily: "Trebuchet MS", lineHeight: 1.15), Text(child: "Enter your email; a link to choose a new one follows.", size: FontSize.sm, color: Color.textMuted, fontFamily: "Trebuchet MS", fontStyle: FontStyle.italic), Divider(), Form(id: "resetPassword", onSubmit: ResetPreviewPassword(), child: Column(gap: Space.md, children: [TextField(name: "email", label: "Your email", type: InputType.email, required: true, background: Color.surface, border: Border(width: 1, color: Color.border), radius: Radius.sm), SubmitButton(label: "SEND THE LINK", fullWidth: true)])), Button(label: "BACK TO THE MENU", style: ButtonStyle.ghost, icon: Icons.chevronLeft, onTap: Navigate(to: Route.menu))
  ])])),
  )
)
